-- Additive physical file evidence. Existing 086/092 histories and hashes are untouched.
CREATE TABLE stock_file_import_previews(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,scope_hash text NOT NULL,file_name text NOT NULL,payload jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),CHECK(request_hash~'^[a-f0-9]{64}$' AND scope_hash~'^[a-f0-9]{64}$'),CHECK(octet_length(payload::text)<=33554432)
);
CREATE TABLE stock_file_import_executions(
 id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,preview_id uuid NOT NULL,client_key uuid NOT NULL,request_hash text NOT NULL,scope_hash text NOT NULL,file_name text NOT NULL,payload jsonb NOT NULL,top_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),transaction_started_at timestamptz NOT NULL DEFAULT transaction_timestamp(),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),UNIQUE(tenant_id,preview_id),FOREIGN KEY(tenant_id,preview_id) REFERENCES stock_file_import_previews(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id),CHECK(request_hash~'^[a-f0-9]{64}$' AND scope_hash~'^[a-f0-9]{64}$'),CHECK(octet_length(payload::text)<=33554432)
);
CREATE TABLE stock_file_import_profiles(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants,version integer NOT NULL CHECK(version>0),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id));
CREATE TABLE stock_file_import_profile_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants,profile_id uuid NOT NULL,version integer NOT NULL,actor_id uuid NOT NULL REFERENCES users,api_key_id uuid,client_key uuid NOT NULL,request_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,client_key),UNIQUE(tenant_id,profile_id,version),FOREIGN KEY(tenant_id,profile_id) REFERENCES stock_file_import_profiles(tenant_id,id),FOREIGN KEY(tenant_id,api_key_id) REFERENCES api_keys(tenant_id,id));
CREATE TABLE stock_file_import_admissions(tenant_id uuid NOT NULL,preview_id uuid NOT NULL,execution_id uuid NOT NULL,actor_id uuid NOT NULL,api_key_id uuid,request jsonb NOT NULL,before_snapshot jsonb NOT NULL,after_snapshot jsonb,top_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),transaction_started_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,execution_id),UNIQUE(tenant_id,preview_id),FOREIGN KEY(tenant_id,preview_id) REFERENCES stock_file_import_previews(tenant_id,id),FOREIGN KEY(tenant_id,execution_id) REFERENCES stock_file_import_executions(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE stock_file_import_core_witnesses(tenant_id uuid NOT NULL,kind text NOT NULL,id uuid NOT NULL,preview_id uuid NOT NULL,top_xid xid8 NOT NULL,transaction_started_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,kind,id),FOREIGN KEY(tenant_id,preview_id) REFERENCES stock_file_import_previews(tenant_id,id));
CREATE TABLE stock_file_import_epochs(tenant_id uuid NOT NULL,warehouse_id uuid NOT NULL,product_id uuid NOT NULL,version bigint NOT NULL CHECK(version>0),PRIMARY KEY(tenant_id,warehouse_id,product_id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,product_id) REFERENCES products(tenant_id,id));
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['stock_file_import_previews','stock_file_import_executions','stock_file_import_profiles','stock_file_import_profile_revisions','stock_file_import_admissions','stock_file_import_core_witnesses','stock_file_import_epochs'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);
 EXECUTE format('CREATE POLICY tenant_scope ON %I TO dyna_app USING(tenant_id=(SELECT nullif(current_setting(''app.tenant_id'',true),'''')::uuid)) WITH CHECK(tenant_id=(SELECT nullif(current_setting(''app.tenant_id'',true),'''')::uuid))',n);
 EXECUTE format('CREATE POLICY owner_scope ON %I TO %I USING(true) WITH CHECK(true)',n,current_user);
 REVOKE ALL ON stock_file_import_admissions,stock_file_import_core_witnesses,stock_file_import_epochs FROM PUBLIC,dyna_app;
 IF n IN('stock_file_import_previews','stock_file_import_executions','stock_file_import_profiles','stock_file_import_profile_revisions') THEN EXECUTE format('GRANT SELECT ON %I TO dyna_app',n);EXECUTE format('CREATE INDEX ON %I(tenant_id,created_at DESC,id DESC)',n);END IF;
 END LOOP;END $$;
CREATE FUNCTION stock_file_import_installed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT EXISTS(SELECT 1 FROM migrations WHERE name='115_stock_file_imports') $$;
CREATE FUNCTION stock_file_import_access(uid uuid,kid uuid,writing boolean,pin boolean) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;r text;k api_keys%ROWTYPE;valid boolean:=true;allowed boolean;canwrite boolean;value boolean;lots boolean;BEGIN
 IF t IS NULL OR uid IS NULL THEN RETURN jsonb_build_object('allowed',false,'key_valid',false);END IF;
 IF pin THEN SELECT role INTO r FROM memberships WHERE tenant_id=t AND user_id=uid FOR SHARE;ELSE SELECT role INTO r FROM memberships WHERE tenant_id=t AND user_id=uid;END IF;
 allowed:=coalesce(r IN('admin','operator','viewer'),false);canwrite:=r='admin';value:=r='admin';SELECT coalesce((SELECT enabled FROM wms_policies WHERE tenant_id=t),false) INTO lots;
 IF kid IS NOT NULL THEN
  IF pin THEN SELECT * INTO k FROM api_keys WHERE tenant_id=t AND id=kid AND user_id=uid FOR SHARE;ELSE SELECT * INTO k FROM api_keys WHERE tenant_id=t AND id=kid AND user_id=uid;END IF;
  valid:=FOUND AND k.revoked_at IS NULL AND(k.expires_at IS NULL OR k.expires_at>clock_timestamp());allowed:=allowed AND valid AND coalesce(k.scopes @> ARRAY['products:read','inventory:read']::text[],false);canwrite:=canwrite AND allowed AND coalesce(k.scopes @> ARRAY['inventory:write']::text[],false) AND (NOT lots OR coalesce(k.scopes @> ARRAY['purchasing:read','purchasing:write']::text[],false));value:=value AND valid AND coalesce(k.scopes @> ARRAY['purchasing:read']::text[],false);
 END IF;
 RETURN jsonb_build_object('role',r,'key_valid',valid,'allowed',coalesce(allowed AND(NOT writing OR canwrite),false),'can_write',coalesce(canwrite,false),'can_read_value',coalesce(value,false));END $$;
CREATE FUNCTION stock_file_import_require(uid uuid,kid uuid,pin boolean) RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE g jsonb;BEGIN g:=stock_file_import_access(uid,kid,true,pin);IF(g->>'key_valid')::boolean IS FALSE THEN RAISE EXCEPTION 'Wycofany klucz importu stanów' USING ERRCODE='23514';END IF;IF(g->>'allowed')::boolean IS NOT TRUE THEN RAISE EXCEPTION 'Brak aktualnej zgody importu stanów' USING ERRCODE='23514';END IF;END $$;
CREATE FUNCTION stock_file_import_canonical(j jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$ DECLARE answer text;BEGIN
 IF jsonb_typeof(j)='object' THEN SELECT '{'||coalesce(string_agg(to_jsonb(k)::text||':'||stock_file_import_canonical(v),',' ORDER BY k COLLATE "C"),'')||'}' INTO answer FROM jsonb_each(j) x(k,v);RETURN answer;END IF;
 IF jsonb_typeof(j)='array' THEN SELECT '['||coalesce(string_agg(stock_file_import_canonical(v),',' ORDER BY ord),'')||']' INTO answer FROM jsonb_array_elements(j) WITH ORDINALITY x(v,ord);RETURN answer;END IF;RETURN j::text;END $$;
CREATE FUNCTION stock_file_import_hash(j jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$ SELECT encode(sha256(convert_to(stock_file_import_canonical(j),'UTF8')),'hex') $$;
CREATE FUNCTION stock_file_import_record(j jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$ DECLARE k text;BEGIN FOREACH k IN ARRAY ARRAY['version','fifo_sequence','unit_cost_minor','policy_version','value_minor','value_delta'] LOOP IF j ? k THEN j:=j||jsonb_build_object(k,j->>k);END IF;END LOOP;RETURN j;END $$;
CREATE FUNCTION stock_file_import_snapshot(d jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;ps uuid[];ws uuid[];result jsonb:='{}';name text;data jsonb;BEGIN
 IF t IS NULL THEN RAISE EXCEPTION 'Brak własnego zakresu pomiarów' USING ERRCODE='42501';END IF;
 SELECT ARRAY(SELECT jsonb_array_elements_text(d->'product_ids')::uuid),ARRAY(SELECT jsonb_array_elements_text(d->'warehouse_ids')::uuid) INTO ps,ws;
 SELECT jsonb_build_object('products',coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]'::jsonb)) INTO result FROM products p WHERE tenant_id=t AND id=ANY(ps);
 FOR name IN SELECT unnest(ARRAY['stock','stock_locations','reservations','reservation_locations','wms_layer_positions','wms_reservation_layers','stock_file_import_epochs']) LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(stock_file_import_record(to_jsonb(p)) ORDER BY to_jsonb(p)::text COLLATE "C"),''[]''::jsonb) FROM %I p WHERE tenant_id=$1 AND product_id=ANY($2) AND warehouse_id=ANY($3)',name) INTO data USING t,ps,ws;
  result:=result||jsonb_build_object(CASE name WHEN 'stock_locations' THEN 'bins' WHEN 'wms_layer_positions' THEN 'layer_positions' WHEN 'wms_reservation_layers' THEN 'reservation_layers' WHEN 'stock_file_import_epochs' THEN 'epochs' ELSE name END,data);
 END LOOP;
 FOR name IN SELECT unnest(ARRAY['wms_lots','wms_cost_layers']) LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(stock_file_import_record(to_jsonb(p)) ORDER BY to_jsonb(p)::text COLLATE "C"),''[]''::jsonb) FROM %I p WHERE tenant_id=$1 AND product_id=ANY($2)',name) INTO data USING t,ps;
  result:=result||jsonb_build_object(CASE name WHEN 'wms_cost_layers' THEN 'layers' ELSE 'lots' END,data);
 END LOOP;
 FOR name IN SELECT unnest(ARRAY['wms_operations','wms_layer_movements','stock_movements','stock_location_movements','stock_location_operations']) LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(stock_file_import_record(to_jsonb(p)) ORDER BY to_jsonb(p)::text COLLATE "C"),''[]''::jsonb) FROM %I p WHERE tenant_id=$1',name) INTO data USING t;
  result:=result||jsonb_build_object(name,data);
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(w) ORDER BY w.id),'[]') INTO data FROM warehouses w WHERE tenant_id=t AND id=ANY(ws);result:=result||jsonb_build_object('warehouses',data);
 SELECT stock_file_import_record(to_jsonb(p)) INTO data FROM wms_policies p WHERE tenant_id=t;result:=result||jsonb_build_object('policy',data);
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.product_id,a.sku),'[]') INTO data FROM product_sku_aliases a WHERE tenant_id=t AND product_id=ANY(ps);result:=result||jsonb_build_object('aliases',data);
 IF octet_length(result::text)>33554432 THEN RAISE EXCEPTION 'Pełny zakres pomiarów przekracza 32 MiB' USING ERRCODE='P0001';END IF;RETURN result;
END $$;
CREATE FUNCTION stock_file_import_epoch() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE d jsonb:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;BEGIN
 IF to_regclass('public.stock_file_import_epochs') IS NULL THEN RETURN coalesce(NEW,OLD);END IF;
 INSERT INTO stock_file_import_epochs(tenant_id,warehouse_id,product_id,version) VALUES((d->>'tenant_id')::uuid,(d->>'warehouse_id')::uuid,(d->>'product_id')::uuid,1) ON CONFLICT(tenant_id,warehouse_id,product_id) DO UPDATE SET version=stock_file_import_epochs.version+1;RETURN coalesce(NEW,OLD);END $$;
CREATE TRIGGER stock_file_epoch AFTER INSERT OR DELETE ON stock FOR EACH ROW EXECUTE FUNCTION stock_file_import_epoch();
CREATE FUNCTION stock_file_import_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN RAISE EXCEPTION 'Dowód importu stanów jest niezmienny' USING ERRCODE='23514';END $$;
CREATE FUNCTION stock_file_import_budget() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE n bigint;records bigint;name text;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('stock-file:'||NEW.tenant_id,0));
 SELECT count(*) INTO records FROM stock_file_import_previews WHERE tenant_id=NEW.tenant_id;IF records>2000 THEN RAISE EXCEPTION 'Limit historii importu stanów' USING ERRCODE='P0001';END IF;
 SELECT count(*) INTO records FROM stock_file_import_profiles WHERE tenant_id=NEW.tenant_id;IF records>100 THEN RAISE EXCEPTION 'Limit profili importu stanów' USING ERRCODE='P0001';END IF;
 n:=0;FOR name IN SELECT unnest(ARRAY['stock_file_import_previews','stock_file_import_executions','stock_file_import_profiles','stock_file_import_profile_revisions','stock_file_import_admissions','stock_file_import_core_witnesses']) LOOP EXECUTE format('SELECT coalesce(sum(octet_length(to_jsonb(p)::text)),0) FROM %I p WHERE tenant_id=$1',name) INTO records USING NEW.tenant_id;n:=n+records;END LOOP;
 IF n>268435456 THEN RAISE EXCEPTION 'Budżet dowodów importu stanów' USING ERRCODE='P0001';END IF;RETURN NEW;END $$;
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['stock_file_import_previews','stock_file_import_executions','stock_file_import_profiles','stock_file_import_profile_revisions'] LOOP
 IF n='stock_file_import_profiles' THEN EXECUTE format('CREATE TRIGGER immutable BEFORE DELETE ON %I FOR EACH ROW EXECUTE FUNCTION stock_file_import_immutable()',n);ELSE EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION stock_file_import_immutable()',n);END IF;
 EXECUTE format('CREATE TRIGGER budget AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION stock_file_import_budget()',n);
 END LOOP;END $$;
-- Source decoder independent of application-provided normalized rows.
CREATE FUNCTION stock_file_import_xml_value(x xml) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$ DECLARE ty text;child xml;name text;answer jsonb;v text;BEGIN
 IF (xpath('string(/*/@nil)',x))[1]::text='true' THEN RETURN 'null'::jsonb;END IF;ty:=coalesce((xpath('string(/*/@type)',x))[1]::text,'');v:=(xpath('string(/*)',x))[1]::text;
 IF ty='null' THEN RETURN 'null'::jsonb;ELSIF ty='number' THEN RETURN v::jsonb;ELSIF ty='boolean' THEN RETURN v::jsonb;ELSIF ty='array' THEN answer:='[]';FOREACH child IN ARRAY xpath('/*/*',x) LOOP answer:=answer||jsonb_build_array(stock_file_import_xml_value(child));END LOOP;RETURN answer;ELSIF ty='object' THEN answer:='{}';FOREACH child IN ARRAY xpath('/*/*',x) LOOP name:=(xpath('string(/*/@key)',child))[1]::text;answer:=answer||jsonb_build_object(name,stock_file_import_xml_value(child));END LOOP;RETURN answer;END IF;RETURN to_jsonb(v);
END $$;
CREATE FUNCTION stock_file_import_source_cells(request jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$
DECLARE content text:=regexp_replace(request->>'content','^'||chr(65279),'');delim text:=request#>>'{definition,delimiter}';answer jsonb:='[]';records jsonb:='[]';cells jsonb:='[]';headers jsonb;obj jsonb;cell text:='';quoted boolean:=false;closed boolean:=false;i integer:=1;ch text;doc xml;rownode xml;fieldnode xml;name text;BEGIN
 IF request#>>'{definition,format}'='xml' THEN
  IF content~*'<!\s*(DOCTYPE|ENTITY)' THEN RAISE EXCEPTION 'DTD i encje są zabronione' USING ERRCODE='23514';END IF;doc:=xmlparse(document content);
  FOREACH rownode IN ARRAY xpath(CASE WHEN request#>>'{definition,xml_mode}'='positions' THEN '/dynaminds-stock-counts/row' ELSE '/catalog/product' END,doc) LOOP
   obj:='{}';FOREACH fieldnode IN ARRAY xpath('/*/*',rownode) LOOP
    IF request#>>'{definition,xml_mode}'='positions' THEN name:=(xpath('string(/*/@name)',fieldnode))[1]::text;obj:=obj||jsonb_build_object(name,(xpath('string(/*)',fieldnode))[1]::text);
    ELSE name:=(xpath('local-name(/*)',fieldnode))[1]::text;obj:=obj||jsonb_build_object(name,stock_file_import_xml_value(fieldnode));END IF;
   END LOOP;answer:=answer||jsonb_build_array(obj);
  END LOOP;RETURN answer;
 END IF;
 WHILE i<=length(content) LOOP
  ch:=substr(content,i,1);
  IF quoted THEN IF ch='"' THEN IF substr(content,i+1,1)='"' THEN cell:=cell||'"';i:=i+1;ELSE quoted:=false;closed:=true;END IF;ELSE cell:=cell||ch;END IF;
  ELSIF ch=delim THEN cells:=cells||jsonb_build_array(cell);cell:='';closed:=false;
  ELSIF ch IN(chr(10),chr(13)) THEN IF ch=chr(13) AND substr(content,i+1,1)=chr(10) THEN i:=i+1;END IF;records:=records||jsonb_build_array(cells||jsonb_build_array(cell));cells:='[]';cell:='';closed:=false;
  ELSIF ch='"' THEN IF cell<>'' OR closed THEN RAISE EXCEPTION 'Niepoprawny CSV' USING ERRCODE='23514';END IF;quoted:=true;
  ELSE IF closed THEN RAISE EXCEPTION 'Niepoprawny CSV' USING ERRCODE='23514';END IF;cell:=cell||ch;END IF;i:=i+1;
 END LOOP;
 IF quoted THEN RAISE EXCEPTION 'Niepoprawny CSV' USING ERRCODE='23514';END IF;IF cell<>'' OR jsonb_array_length(cells)>0 OR closed THEN records:=records||jsonb_build_array(cells||jsonb_build_array(cell));END IF;
 headers:=records->0;FOR i IN 1..jsonb_array_length(records)-1 LOOP obj:='{}';FOR name,ch IN SELECT h.value,r.value FROM jsonb_array_elements_text(headers) WITH ORDINALITY h(value,ord) LEFT JOIN jsonb_array_elements_text(records->i) WITH ORDINALITY r(value,ord) USING(ord) LOOP obj:=obj||jsonb_build_object(name,coalesce(ch,''));END LOOP;answer:=answer||jsonb_build_array(obj);END LOOP;RETURN answer;
END $$;
CREATE FUNCTION stock_file_import_cell(value text,safe boolean,identity boolean DEFAULT false) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$ SELECT CASE WHEN safe AND left(value,1)='''' AND(identity OR substr(value,2)~'^[[:space:]]*[=+\-@]' OR substr(value,2,1) IN(chr(9),chr(10),chr(13)) OR substr(value,2)~'^[[:space:]]*[+-]?[0-9]+([.,][0-9]+)?([eE][+-]?[0-9]+)?[[:space:]]*$') THEN substr(value,2) ELSE value END $$;
CREATE FUNCTION stock_file_import_configuration(d jsonb,targets jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $$ DECLARE q jsonb;k text;v jsonb;BEGIN
 IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR NOT d ?& ARRAY['format','xml_mode','delimiter','identity','identity_field','spreadsheet_safe','empty_policy'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(d) x WHERE x NOT IN('format','xml_mode','delimiter','identity','identity_field','spreadsheet_safe','empty_policy')) OR EXISTS(SELECT 1 FROM unnest(ARRAY['format','xml_mode','delimiter','identity','empty_policy']) field WHERE jsonb_typeof(d->field) IS DISTINCT FROM 'string') OR d->>'format' NOT IN('csv','xml') OR d->>'xml_mode' NOT IN('positions','catalog') OR d->>'delimiter' NOT IN(';',',',chr(9)) OR d->>'identity' NOT IN('uuid','sku','historical_sku','ean','name') OR d->>'empty_policy' NOT IN('skip','error') OR jsonb_typeof(d->'spreadsheet_safe') IS DISTINCT FROM 'boolean' OR jsonb_typeof(d->'identity_field') IS DISTINCT FROM 'string' OR length(d->>'identity_field') NOT BETWEEN 1 AND 80 OR jsonb_typeof(targets) IS DISTINCT FROM 'array' OR jsonb_array_length(targets) NOT BETWEEN 1 AND 8 THEN RETURN false;END IF;
 IF(SELECT count(DISTINCT x->>'warehouse_id') FROM jsonb_array_elements(targets) x)<>jsonb_array_length(targets) THEN RETURN false;END IF;
 FOR q IN SELECT value FROM jsonb_array_elements(targets) LOOP
  IF NOT q ?& ARRAY['warehouse_id','quantity_scope','mapping','default_location'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(q) x WHERE x NOT IN('warehouse_id','quantity_scope','mapping','default_location')) OR jsonb_typeof(q->'quantity_scope') IS DISTINCT FROM 'string' OR jsonb_typeof(q->'warehouse_id') IS DISTINCT FROM 'string' OR q->>'quantity_scope' NOT IN('position','warehouse_total') OR q->>'warehouse_id'!~'^[a-f0-9-]{36}$' OR jsonb_typeof(q->'mapping') IS DISTINCT FROM 'object' OR NOT(q->'mapping' ? 'quantity') OR q->'default_location'<>'null'::jsonb AND(jsonb_typeof(q->'default_location')<>'string' OR length(q->>'default_location') NOT BETWEEN 1 AND 80) THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(q->'mapping') m WHERE m.key NOT IN('quantity','location','operation','lot_id','lot_code','expiry_date','unit_cost_minor','currency') OR jsonb_typeof(m.value)<>'string' OR length(m.value#>>'{}') NOT BETWEEN 1 AND 80 OR m.value#>>'{}'=d->>'identity_field') OR(SELECT count(DISTINCT value) FROM jsonb_each(q->'mapping'))<>(SELECT count(*) FROM jsonb_each(q->'mapping')) THEN RETURN false;END IF;
 END LOOP;RETURN true;
END $$;
CREATE FUNCTION stock_file_import_summary(rows jsonb,whole boolean) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $$
 SELECT jsonb_build_object('positions',jsonb_array_length(rows),'changed',count(*) FILTER(WHERE r->>'status'='changed'),'unchanged',count(*) FILTER(WHERE r->>'status'='unchanged' OR NOT whole AND r->>'status'='skipped'),'invalid',count(*) FILTER(WHERE r->>'status'='invalid'),'conflicts',count(*) FILTER(WHERE r->>'status'='conflict'),'unknown_loss_quantity',coalesce(sum((r#>>'{valuation,unknown_loss_quantity}')::integer),0),'surplus_quantity',coalesce(sum((r#>>'{valuation,surplus_quantity}')::integer),0)) || CASE WHEN whole THEN jsonb_build_object('skipped',count(*) FILTER(WHERE r->>'status'='skipped'),'products',count(DISTINCT r->>'product_id')) ELSE '{}'::jsonb END FROM jsonb_array_elements(rows) r
$$;
CREATE FUNCTION stock_file_import_validate_preview(d jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;source jsonb;r jsonb;target jsonb;raw jsonb;prod products%ROWTYPE;actual jsonb;scope jsonb;qty integer;held integer;totalqty bigint;gotqty bigint;identity text;operation text;amount text;basis jsonb;layer jsonb;fragments jsonb;need integer;free integer;take integer;lotid uuid;sumq bigint;safe boolean:=d#>>'{definition,format}'='csv' AND(d#>>'{definition,spreadsheet_safe}')::boolean;BEGIN
 IF t IS NULL OR d->>'scope_hash' IS DISTINCT FROM stock_file_import_hash(d-'scope_hash') OR d->>'source_hash' IS DISTINCT FROM encode(sha256(convert_to(d#>>'{request,content}','UTF8')),'hex') OR octet_length(d::text)>33554432 OR jsonb_array_length(d->'rows') NOT BETWEEN 1 AND 4000 OR jsonb_array_length(d->'targets') NOT BETWEEN 1 AND 8 THEN RAISE EXCEPTION 'Niepoprawny pełny podgląd pomiarów' USING ERRCODE='23514';END IF;
 PERFORM stock_file_import_require((d->>'actor_id')::uuid,(d->>'api_key_id')::uuid,false);
 IF d->>'source' NOT IN('manual','api') OR d->>'request_hash' IS DISTINCT FROM stock_file_import_hash(jsonb_build_object('actor_id',d->>'actor_id','api_key_id',d->>'api_key_id','source',d->>'source','kind','preview','parent_id',null,'request',d->'request')) THEN RAISE EXCEPTION 'Hash podglądu nie wiąże aktora i źródła' USING ERRCODE='23514';END IF;
 IF d->'definition' IS DISTINCT FROM d#>'{request,definition}' OR d->>'file_name' IS DISTINCT FROM d#>>'{request,file_name}' OR d->>'note' IS DISTINCT FROM d#>>'{request,note}' THEN RAISE EXCEPTION 'Konfiguracja pomiaru różni się od źródła' USING ERRCODE='23514';END IF;
 IF NOT stock_file_import_configuration(d->'definition',d#>'{request,targets}') THEN RAISE EXCEPTION 'Niepoprawna konfiguracja pomiaru' USING ERRCODE='23514';END IF;source:=stock_file_import_source_cells(d->'request');IF jsonb_array_length(source) NOT BETWEEN 1 AND 500 OR(d#>>'{summary,source_rows}')::integer<>jsonb_array_length(source) OR(d#>>'{summary,positions}')::integer<>jsonb_array_length(d->'rows') THEN RAISE EXCEPTION 'Niepełne wiersze pomiarów' USING ERRCODE='23514';END IF;
 SELECT jsonb_build_object('warehouse_ids',jsonb_agg(x->'warehouse_id'),'product_ids',(SELECT coalesce(jsonb_agg(p->'id'),'[]') FROM jsonb_array_elements(d#>'{snapshot,products}') p)) INTO scope FROM jsonb_array_elements(d->'targets') x;
 actual:=stock_file_import_snapshot(scope);IF actual IS DISTINCT FROM d->'snapshot' THEN RAISE EXCEPTION 'Rzeczywisty zakres pomiarów zmienił się' USING ERRCODE='23514';END IF;
 IF coalesce((actual#>>'{policy,enabled}')::boolean,false) IS DISTINCT FROM(d#>>'{policy,enabled}')::boolean OR coalesce(actual#>>'{policy,version}','0') IS DISTINCT FROM d#>>'{policy,version}' THEN RAISE EXCEPTION 'Polityka pomiarów jest nieaktualna' USING ERRCODE='23514';END IF;
 FOR target IN SELECT value FROM jsonb_array_elements(d->'targets') LOOP
 IF NOT EXISTS(SELECT 1 FROM warehouses WHERE tenant_id=t AND id=(target->>'warehouse_id')::uuid) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d#>'{request,targets}') q WHERE q=target-ARRAY['warehouse_name','summary','valuation','children']) THEN RAISE EXCEPTION 'Obcy magazyn lub mapowanie pomiarów' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(d->'rows') LOOP
  raw:=source->(r->>'source_index')::integer;
  IF raw IS NULL OR raw IS DISTINCT FROM r->'raw_cells' THEN RAISE EXCEPTION 'Źródłowy wiersz pomiaru różni się od dowodu' USING ERRCODE='23514';END IF;
  SELECT value INTO target FROM jsonb_array_elements(d->'targets') x WHERE x->>'warehouse_id'=r->>'warehouse_id';
  IF target IS NULL THEN RAISE EXCEPTION 'Wiersz poza magazynami' USING ERRCODE='23514';END IF;
  identity:=nullif(stock_file_import_cell(raw->>(d#>>'{definition,identity_field}'),safe,d#>>'{definition,identity}' IN('uuid','sku','historical_sku','ean')),'');IF d#>>'{definition,identity}'='uuid' THEN IF identity~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN identity:=lower(identity);ELSE identity:=NULL;END IF;END IF;
  IF r#>>'{resolution,value}' IS DISTINCT FROM identity THEN RAISE EXCEPTION 'Źródłowy identyfikator różni się od rozwiązania' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(r->'errors') IS DISTINCT FROM 'array' OR r->>'status' NOT IN('invalid','unchanged','changed','skipped','conflict') OR(r->>'status' NOT IN('invalid','conflict') AND jsonb_array_length(r->'errors')<>0) THEN RAISE EXCEPTION 'Niepoprawny stan wiersza pomiaru' USING ERRCODE='23514';END IF;IF r->>'status'='invalid' THEN CONTINUE;END IF;
  SELECT * INTO prod FROM products p WHERE tenant_id=t AND id=(r->>'product_id')::uuid;
  IF prod.id IS NULL OR NOT prod.active OR prod.kind NOT IN('simple','variant') OR prod.sku IS DISTINCT FROM r->>'sku' OR prod.name IS DISTINCT FROM r->>'name' THEN RAISE EXCEPTION 'Brak własnego fizycznego produktu' USING ERRCODE='23514';END IF;
  IF (SELECT count(*) FROM products p WHERE tenant_id=t AND CASE d#>>'{definition,identity}' WHEN 'uuid' THEN p.id::text=identity WHEN 'sku' THEN p.sku=identity WHEN 'historical_sku' THEN p.sku=identity OR EXISTS(SELECT 1 FROM product_sku_aliases a WHERE(a.tenant_id,a.product_id)=(p.tenant_id,p.id) AND a.sku=identity) WHEN 'ean' THEN p.ean<>'' AND p.ean=identity ELSE p.name=identity END)<>1 OR NOT(CASE d#>>'{definition,identity}' WHEN 'uuid' THEN prod.id::text=identity WHEN 'sku' THEN prod.sku=identity WHEN 'historical_sku' THEN prod.sku=identity OR EXISTS(SELECT 1 FROM product_sku_aliases a WHERE(a.tenant_id,a.product_id)=(prod.tenant_id,prod.id) AND a.sku=identity) WHEN 'ean' THEN prod.ean=identity ELSE prod.name=identity END) THEN RAISE EXCEPTION 'Tożsamość produktu jest niejednoznaczna' USING ERRCODE='23514';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each_text(target->'mapping') m WHERE NOT(raw ? m.value)) THEN RAISE EXCEPTION 'Brak mapowanego pola pomiaru' USING ERRCODE='23514';END IF;operation:=stock_file_import_cell(raw->>(target#>>'{mapping,operation}'),safe);amount:=stock_file_import_cell(raw->>(target#>>'{mapping,quantity}'),safe);
  IF d#>>'{definition,format}'='xml' AND d#>>'{definition,xml_mode}'='catalog' THEN SELECT x->>'on_hand' INTO amount FROM jsonb_array_elements(raw->(target#>>'{mapping,quantity}')) x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'status'='available' AND x->>'source'='stock';END IF;
  IF r#>>'{input,operation}'='none' THEN IF r->>'status' IS DISTINCT FROM 'skipped' OR r->'before' IS DISTINCT FROM 'null'::jsonb OR r->'after' IS DISTINCT FROM 'null'::jsonb OR r->'valuation' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Pominięty wiersz nie jest pominiętą pozycją' USING ERRCODE='23514';END IF;IF operation IS DISTINCT FROM 'none' AND(amount IS NOT NULL AND amount<>'') THEN RAISE EXCEPTION 'Pominięto rzeczywisty pomiar' USING ERRCODE='23514';END IF;CONTINUE;END IF;
  IF r#>>'{input,operation}' IS DISTINCT FROM 'count' OR operation NOT IN('','count') AND operation IS NOT NULL OR amount IS NULL OR amount!~'^(0|[1-9][0-9]{0,9})$' OR amount::numeric>2147483647 OR(r#>>'{input,quantity}') IS NULL OR(r#>>'{input,quantity}')!~'^(0|[1-9][0-9]{0,6})$' OR(r#>>'{input,quantity}')::integer>1000000 THEN RAISE EXCEPTION 'Źródłowy pomiar różni się od zatwierdzonego' USING ERRCODE='23514';END IF;
  SELECT coalesce(sum((x#>>'{input,quantity}')::bigint),0) INTO sumq FROM jsonb_array_elements(d->'rows') x WHERE x->>'source_index'=r->>'source_index' AND x->>'warehouse_id'=r->>'warehouse_id';
  IF sumq<>amount::bigint THEN RAISE EXCEPTION 'Rozkład nie pokrywa źródłowego pomiaru' USING ERRCODE='23514';END IF;
  IF (d#>>'{summary,invalid}')::integer=0 AND EXISTS(SELECT 1 FROM jsonb_array_elements(d->'rows') x WHERE x->>'index'<>r->>'index' AND x->>'product_id'=r->>'product_id' AND x->>'warehouse_id'=r->>'warehouse_id' AND x->>'location'=r->>'location' AND x->'lot'=r->'lot' AND x#>>'{input,operation}'='count') THEN RAISE EXCEPTION 'Powtórzona fizyczna pozycja pomiaru' USING ERRCODE='23514';END IF;
  IF target->>'quantity_scope'='warehouse_total' THEN
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d#>'{request,resolutions}') q WHERE q->>'source_index'=r->>'source_index' AND q->>'warehouse_id'=r->>'warehouse_id') THEN RAISE EXCEPTION 'Agregat wymaga jawnego rozkładu' USING ERRCODE='23514';END IF;
   IF(d#>>'{policy,enabled}')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'layer_positions') lp JOIN jsonb_array_elements(actual->'layers') cl ON cl->>'id'=lp->>'layer_id' WHERE lp->>'product_id'=r->>'product_id' AND lp->>'warehouse_id'=r->>'warehouse_id' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'rows') selected_position WHERE selected_position->>'product_id'=r->>'product_id' AND selected_position->>'warehouse_id'=r->>'warehouse_id' AND selected_position->>'location'=lp->>'location' AND selected_position#>>'{lot,id}'=cl->>'lot_id')) THEN RAISE EXCEPTION 'Rozkład pomija istniejącą partię' USING ERRCODE='23514';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'bins') b WHERE b->>'product_id'=r->>'product_id' AND b->>'warehouse_id'=r->>'warehouse_id' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'rows') x WHERE x->>'product_id'=r->>'product_id' AND x->>'warehouse_id'=r->>'warehouse_id' AND x->>'location'=b->>'location')) THEN RAISE EXCEPTION 'Rozkład pomija istniejący bin' USING ERRCODE='23514';END IF;
  END IF;
  SELECT x INTO basis FROM jsonb_array_elements(actual->'stock') x WHERE x->>'product_id'=r->>'product_id' AND x->>'warehouse_id'=r->>'warehouse_id';
  IF r#>>'{before,present}' IS DISTINCT FROM (basis IS NOT NULL)::text OR coalesce(basis->>'on_hand','0') IS DISTINCT FROM r#>>'{before,warehouse_on_hand}' OR coalesce(basis->>'reserved','0') IS DISTINCT FROM r#>>'{before,warehouse_reserved}' OR coalesce(basis->>'version',CASE WHEN(d#>>'{policy,enabled}')::boolean THEN '0' ELSE NULL END) IS DISTINCT FROM r#>>'{before,stock_version}' THEN RAISE EXCEPTION 'Stan przed pomiarem nie jest rzeczywisty' USING ERRCODE='23514';END IF;
  qty:=0;held:=0;
  IF(d#>>'{policy,enabled}')::boolean THEN
   IF r->'lot' IS NULL OR r->'lot'='null' THEN RAISE EXCEPTION 'WMS wymaga rzeczywistej partii' USING ERRCODE='23514';END IF;lotid:=(r#>>'{lot,id}')::uuid;
   IF lotid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM wms_lots WHERE tenant_id=t AND id=lotid AND product_id=prod.id) THEN RAISE EXCEPTION 'Obca partia pomiaru' USING ERRCODE='23514';END IF;
   SELECT coalesce(sum(p.quantity),0),coalesce(sum(p.reserved),0) INTO qty,held FROM wms_layer_positions p JOIN wms_cost_layers l ON(l.tenant_id,l.id)=(p.tenant_id,p.layer_id) WHERE p.tenant_id=t AND p.warehouse_id=(r->>'warehouse_id')::uuid AND p.product_id=prod.id AND p.location=r->>'location' AND l.lot_id=lotid;
   need:=(r#>>'{input,quantity}')::integer-qty;fragments:='[]';
   IF need>0 THEN
    IF r#>>'{position,unit_cost_minor}' IS NULL OR r#>>'{position,unit_cost_minor}'!~'^(0|[1-9][0-9]*)$' OR(r#>>'{position,unit_cost_minor}')::numeric>9223372036854775807 OR r#>>'{position,currency}' IS DISTINCT FROM d#>>'{policy,currency}' THEN RAISE EXCEPTION 'Nadwyżka wymaga jawnego kosztu i waluty polityki' USING ERRCODE='23514';END IF;
    fragments:=jsonb_build_array(jsonb_build_object('layer_id',null,'quantity',need,'delta',need,'unit_cost_minor',r#>>'{position,unit_cost_minor}','currency',r#>>'{position,currency}'));
   ELSIF need<0 THEN need:=-need;
    FOR layer IN SELECT stock_file_import_record(to_jsonb(x)) FROM(SELECT p.layer_id,p.quantity,p.reserved,l.unit_cost_minor,l.currency FROM wms_layer_positions p JOIN wms_cost_layers l ON(l.tenant_id,l.id)=(p.tenant_id,p.layer_id) WHERE p.tenant_id=t AND p.warehouse_id=(r->>'warehouse_id')::uuid AND p.product_id=prod.id AND p.location=r->>'location' AND l.lot_id=lotid ORDER BY l.fifo_sequence,l.id) x LOOP
     free:=(layer->>'quantity')::integer-(layer->>'reserved')::integer;take:=least(need,free);IF take>0 THEN fragments:=fragments||jsonb_build_array(jsonb_build_object('layer_id',layer->>'layer_id','quantity',take,'delta',-take,'unit_cost_minor',layer->>'unit_cost_minor','currency',layer->>'currency'));need:=need-take;END IF;EXIT WHEN need=0;
    END LOOP;IF need>0 THEN RAISE EXCEPTION 'Pomiar narusza rezerwacje warstw' USING ERRCODE='23514';END IF;
   END IF;
   IF r->'lot' IS DISTINCT FROM (CASE WHEN r#>>'{position,lot,kind}'='existing' THEN(SELECT jsonb_build_object('id',l.id,'lot_code',l.lot_code,'expiry_date',l.expiry_date::text) FROM wms_lots l WHERE l.tenant_id=t AND l.id=(r#>>'{position,lot,lot_id}')::uuid AND l.product_id=prod.id) ELSE jsonb_build_object('id',null,'lot_code',r#>>'{position,lot,lot_code}','expiry_date',r#>>'{position,lot,expiry_date}') END) THEN RAISE EXCEPTION 'Źródłowa partia różni się od pomiaru' USING ERRCODE='23514';END IF;
   IF r->'valuation' IS DISTINCT FROM(SELECT jsonb_build_object('currency',d#>>'{policy,currency}','known_loss_minor',coalesce(sum((f->>'quantity')::numeric*(f->>'unit_cost_minor')::numeric) FILTER(WHERE(f->>'delta')::integer<0),0)::text,'known_surplus_minor',coalesce(sum((f->>'quantity')::numeric*(f->>'unit_cost_minor')::numeric) FILTER(WHERE(f->>'delta')::integer>0),0)::text,'unknown_loss_quantity',coalesce(sum((f->>'quantity')::integer) FILTER(WHERE f->>'unit_cost_minor' IS NULL),0),'surplus_quantity',greatest((r#>>'{input,quantity}')::integer-qty,0)) FROM jsonb_array_elements(fragments) f) THEN RAISE EXCEPTION 'Wycena pomiaru różni się od rzeczywistych fragmentów' USING ERRCODE='23514';END IF;
   IF fragments IS DISTINCT FROM r->'fragments' THEN RAISE EXCEPTION 'Plan FIFO różni się od rzeczywistych warstw' USING ERRCODE='23514';END IF;
  ELSE
   IF r->'lot' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Wyłączony WMS nie przyjmuje partii' USING ERRCODE='23514';END IF;
   SELECT coalesce((SELECT quantity FROM stock_locations WHERE tenant_id=t AND warehouse_id=(r->>'warehouse_id')::uuid AND product_id=prod.id AND location=r->>'location'),0) INTO qty;
   SELECT coalesce(sum(rl.quantity),0) INTO held FROM reservation_locations rl JOIN reservations rr ON(rr.tenant_id,rr.order_id,rr.product_id,rr.warehouse_id)=(rl.tenant_id,rl.order_id,rl.product_id,rl.warehouse_id) WHERE rl.tenant_id=t AND rl.warehouse_id=(r->>'warehouse_id')::uuid AND rl.product_id=prod.id AND rl.location=r->>'location' AND rr.state='active';
  END IF;
  IF qty IS DISTINCT FROM(r#>>'{before,quantity}')::integer OR held IS DISTINCT FROM(r#>>'{before,reserved}')::integer OR(r#>>'{input,quantity}')::integer<held OR(r#>>'{after,quantity}')::integer IS DISTINCT FROM(r#>>'{input,quantity}')::integer THEN RAISE EXCEPTION 'Fizyczna ilość pomiaru jest nieprawdziwa' USING ERRCODE='23514';END IF;
  IF r->>'status' IS DISTINCT FROM(CASE WHEN qty=(r#>>'{input,quantity}')::integer THEN 'unchanged' ELSE 'changed' END) THEN RAISE EXCEPTION 'Stan wiersza różni się od rzeczywistej zmiany' USING ERRCODE='23514';END IF;
  -- A supplied resolution is bound to every exact position/cost. Otherwise source fields bind it.
  SELECT q INTO basis FROM jsonb_array_elements(d#>'{request,resolutions}') q WHERE q->>'source_index'=r->>'source_index' AND q->>'warehouse_id'=r->>'warehouse_id';
  IF basis IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(basis->'positions') x WHERE x=r->'position') THEN RAISE EXCEPTION 'Pozycja różni się od jawnego rozkładu' USING ERRCODE='23514';END IF;
  ELSE
   IF r#>>'{position,lot,lot_id}' IS DISTINCT FROM nullif(stock_file_import_cell(raw->>(target#>>'{mapping,lot_id}'),safe),'') OR r#>>'{position,lot,lot_code}' IS DISTINCT FROM nullif(stock_file_import_cell(raw->>(target#>>'{mapping,lot_code}'),safe),'') OR r#>>'{position,lot,expiry_date}' IS DISTINCT FROM nullif(stock_file_import_cell(raw->>(target#>>'{mapping,expiry_date}'),safe),'') THEN RAISE EXCEPTION 'Źródłowa partia różni się od rozwiązania' USING ERRCODE='23514';END IF;
   IF r->>'location' IS DISTINCT FROM coalesce(nullif(stock_file_import_cell(raw->>(target#>>'{mapping,location}'),safe),''),target->>'default_location') OR r#>>'{position,unit_cost_minor}' IS DISTINCT FROM nullif(stock_file_import_cell(raw->>(target#>>'{mapping,unit_cost_minor}'),safe),'') OR r#>>'{position,currency}' IS DISTINCT FROM nullif(stock_file_import_cell(raw->>(target#>>'{mapping,currency}'),safe),'') THEN RAISE EXCEPTION 'Źródłowa lokalizacja lub koszt różni się od dowodu' USING ERRCODE='23514';END IF;
  END IF;
 END LOOP;
 IF d->'summary' IS DISTINCT FROM (stock_file_import_summary(d->'rows',true)||jsonb_build_object('source_rows',jsonb_array_length(source))) THEN RAISE EXCEPTION 'Podsumowanie pomiarów nie jest pochodne wierszy' USING ERRCODE='23514';END IF;
 FOR target IN SELECT value FROM jsonb_array_elements(d->'targets') LOOP IF target->'valuation' IS DISTINCT FROM (CASE WHEN(d#>>'{policy,enabled}')::boolean THEN (SELECT jsonb_build_object('currency',d#>>'{policy,currency}','known_loss_minor',coalesce(sum((x#>>'{valuation,known_loss_minor}')::numeric),0)::text,'known_surplus_minor',coalesce(sum((x#>>'{valuation,known_surplus_minor}')::numeric),0)::text) FROM jsonb_array_elements(d->'rows') x WHERE x->>'warehouse_id'=target->>'warehouse_id') ELSE 'null'::jsonb END) THEN RAISE EXCEPTION 'Wycena magazynu nie jest pochodna wierszy' USING ERRCODE='23514';END IF;IF target->'summary' IS DISTINCT FROM stock_file_import_summary((SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(d->'rows') x WHERE x->>'warehouse_id'=target->>'warehouse_id'),false) THEN RAISE EXCEPTION 'Podsumowanie magazynu nie jest pochodne wierszy' USING ERRCODE='23514';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(source) WITH ORDINALITY src(v,n) CROSS JOIN jsonb_array_elements(d->'targets') coverage_target WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'rows') approved_row WHERE(approved_row->>'source_index')::integer=n-1 AND approved_row->>'warehouse_id'=coverage_target->>'warehouse_id')) THEN RAISE EXCEPTION 'Pominięto źródłowy wiersz pomiaru' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION stock_file_import_store_preview(d jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog:'||t,0));PERFORM p.id FROM products p WHERE p.tenant_id=t AND p.id IN(SELECT(x->>'id')::uuid FROM jsonb_array_elements(d#>'{snapshot,products}') x) ORDER BY p.id FOR SHARE;PERFORM stock_file_import_validate_preview(d);
 INSERT INTO stock_file_import_previews(id,tenant_id,actor_id,api_key_id,client_key,request_hash,scope_hash,file_name,payload) VALUES((d->>'id')::uuid,t,(d->>'actor_id')::uuid,(d->>'api_key_id')::uuid,(d->>'client_key')::uuid,d->>'request_hash',d->>'scope_hash',d->>'file_name',d);
END $$;
CREATE FUNCTION stock_file_import_core_admitted(parent uuid,child uuid,mode text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;bound uuid;BEGIN
 IF t IS NULL THEN RETURN false;END IF;
 SELECT p.id INTO bound FROM stock_file_import_previews p CROSS JOIN LATERAL jsonb_array_elements(p.payload->'targets') target CROSS JOIN LATERAL jsonb_array_elements(target->'children') c WHERE p.tenant_id=t AND(c->>'id')::uuid=child;
 IF parent IS NULL THEN RETURN bound IS NULL;END IF;
 RETURN parent IS NOT DISTINCT FROM bound AND EXISTS(SELECT 1 FROM stock_file_import_admissions a JOIN stock_file_import_previews p ON(p.tenant_id,p.id)=(a.tenant_id,a.preview_id) WHERE a.tenant_id=t AND a.preview_id=parent AND a.top_xid=pg_current_xact_id() AND a.transaction_started_at=transaction_timestamp() AND a.after_snapshot IS NULL AND(p.payload#>>'{policy,enabled}')::boolean=(mode='on'));
END $$;
CREATE FUNCTION stock_file_import_prepare(pid uuid,eid uuid,uid uuid,kid uuid,request jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p stock_file_import_previews%ROWTYPE;scope jsonb;BEGIN
 PERFORM purchasing_source_admit();PERFORM stock_file_import_require(uid,kid,false);SELECT * INTO p FROM stock_file_import_previews WHERE tenant_id=t AND id=pid;
 IF p.actor_id IS DISTINCT FROM uid OR p.api_key_id IS DISTINCT FROM kid OR p.id IS NULL OR p.scope_hash IS DISTINCT FROM request->>'scope_hash' OR request->>'confirmed' IS DISTINCT FROM 'true' OR EXISTS(SELECT 1 FROM stock_file_import_executions WHERE tenant_id=t AND preview_id=pid) OR(p.payload#>>'{summary,invalid}')::integer<>0 OR(p.payload#>>'{summary,conflicts}')::integer<>0 THEN RAISE EXCEPTION 'Niepoprawna zgoda na pomiar' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') approved_row WHERE approved_row->>'status' IN('invalid','conflict') OR jsonb_array_length(approved_row->'errors')<>0) THEN RAISE EXCEPTION 'Błędne wiersze nie mogą zostać wykonane' USING ERRCODE='23514';END IF;PERFORM pg_advisory_xact_lock_shared(hashtextextended('catalog:'||t,0));PERFORM prod.id FROM products prod WHERE prod.tenant_id=t AND prod.id IN(SELECT(x->>'id')::uuid FROM jsonb_array_elements(p.payload#>'{snapshot,products}') x) ORDER BY prod.id FOR SHARE;PERFORM stock_file_import_validate_preview(p.payload);
 IF request->'ack_unknown_loss_warehouse_ids' IS DISTINCT FROM(SELECT coalesce(jsonb_agg(x->'warehouse_id' ORDER BY x->>'warehouse_id'),'[]') FROM jsonb_array_elements(p.payload->'targets') x WHERE(x#>>'{summary,unknown_loss_quantity}')::integer>0) OR request->'ack_surplus_warehouse_ids' IS DISTINCT FROM(SELECT coalesce(jsonb_agg(x->'warehouse_id' ORDER BY x->>'warehouse_id'),'[]') FROM jsonb_array_elements(p.payload->'targets') x WHERE(x#>>'{summary,surplus_quantity}')::integer>0) THEN RAISE EXCEPTION 'Zgody wyceny nie odpowiadają magazynom' USING ERRCODE='23514';END IF;
 INSERT INTO stock_file_import_admissions(tenant_id,preview_id,execution_id,actor_id,api_key_id,request,before_snapshot) VALUES(t,pid,eid,uid,kid,request,p.payload->'snapshot');
END $$;
CREATE FUNCTION stock_file_import_core_witness() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE a stock_file_import_admissions%ROWTYPE;child uuid;BEGIN
 IF to_regclass('public.stock_file_import_admissions') IS NULL THEN RETURN NEW;END IF;
 child:=CASE WHEN TG_TABLE_NAME IN('inventory_bulk_edit_executions','wms_stocktake_postings') THEN(to_jsonb(NEW)->>CASE WHEN TG_TABLE_NAME='inventory_bulk_edit_executions' THEN 'preview_id' ELSE 'stocktake_id' END)::uuid ELSE NEW.id END;
 SELECT adm.* INTO a FROM stock_file_import_admissions adm JOIN stock_file_import_previews p ON(p.tenant_id,p.id)=(adm.tenant_id,adm.preview_id) CROSS JOIN LATERAL jsonb_array_elements(p.payload->'targets') target CROSS JOIN LATERAL jsonb_array_elements(target->'children') c WHERE adm.tenant_id=NEW.tenant_id AND(c->>'id')::uuid=child AND adm.top_xid=pg_current_xact_id() AND adm.transaction_started_at=transaction_timestamp();
 IF a.execution_id IS NOT NULL THEN INSERT INTO stock_file_import_core_witnesses(tenant_id,kind,id,preview_id,top_xid,transaction_started_at) VALUES(NEW.tenant_id,TG_TABLE_NAME,NEW.id,a.preview_id,pg_current_xact_id(),transaction_timestamp());
 ELSIF EXISTS(SELECT 1 FROM stock_file_import_previews p CROSS JOIN LATERAL jsonb_array_elements(p.payload->'targets') target CROSS JOIN LATERAL jsonb_array_elements(target->'children') c WHERE p.tenant_id=NEW.tenant_id AND(c->>'id')::uuid=child) THEN RAISE EXCEPTION 'Child pomiar wymaga zatwierdzonego całego importu' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE FUNCTION stock_file_import_validate_execution(d jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;p stock_file_import_previews%ROWTYPE;a stock_file_import_admissions%ROWTYPE;scope jsonb;actual jsonb;link jsonb;target jsonb;child jsonb;r jsonb;stockrow jsonb;binrow jsonb;oldrow jsonb;delta bigint;qty bigint;expected bigint;recorded integer;core inventory_bulk_edit_executions%ROWTYPE;posting wms_stocktake_postings%ROWTYPE;rows_count integer;name text;newrows jsonb;BEGIN
 SELECT * INTO p FROM stock_file_import_previews WHERE tenant_id=t AND id=(d->>'preview_id')::uuid;
 SELECT * INTO a FROM stock_file_import_admissions WHERE tenant_id=t AND execution_id=(d->>'id')::uuid AND top_xid=pg_current_xact_id() AND transaction_started_at=transaction_timestamp();
 IF p.id IS NULL OR a.execution_id IS NULL OR a.preview_id IS DISTINCT FROM p.id OR p.actor_id IS DISTINCT FROM a.actor_id OR p.api_key_id IS DISTINCT FROM a.api_key_id OR(d->>'actor_id')::uuid IS DISTINCT FROM a.actor_id OR(d->>'api_key_id')::uuid IS DISTINCT FROM a.api_key_id OR d->'execute_request' IS DISTINCT FROM a.request OR d->>'scope_hash' IS DISTINCT FROM p.scope_hash OR d->'definition' IS DISTINCT FROM p.payload->'definition' OR d->'targets' IS DISTINCT FROM p.payload->'targets' OR d->'summary' IS DISTINCT FROM p.payload->'summary' OR d->>'source_hash' IS DISTINCT FROM p.payload->>'source_hash' THEN RAISE EXCEPTION 'Niepełne powiązanie wykonania importu stanów' USING ERRCODE='23514';END IF;
 PERFORM stock_file_import_require(a.actor_id,a.api_key_id,false);IF d->>'request_hash' IS DISTINCT FROM stock_file_import_hash(jsonb_build_object('actor_id',a.actor_id::text,'api_key_id',a.api_key_id::text,'source',p.payload->>'source','kind','execute','parent_id',p.id::text,'request',a.request)) THEN RAISE EXCEPTION 'Hash wykonania nie wiąże aktora i zgody' USING ERRCODE='23514';END IF;
 SELECT jsonb_build_object('warehouse_ids',jsonb_agg(x->'warehouse_id'),'product_ids',(SELECT coalesce(jsonb_agg(pr->'id'),'[]') FROM jsonb_array_elements(p.payload#>'{snapshot,products}') pr)) INTO scope FROM jsonb_array_elements(p.payload->'targets') x;
 actual:=stock_file_import_snapshot(scope);
 IF actual IS DISTINCT FROM d->'snapshot' OR actual->'products' IS DISTINCT FROM a.before_snapshot->'products' OR actual->'aliases' IS DISTINCT FROM a.before_snapshot->'aliases' OR actual->'warehouses' IS DISTINCT FROM a.before_snapshot->'warehouses' OR actual->'policy' IS DISTINCT FROM a.before_snapshot->'policy' OR actual->'reservations' IS DISTINCT FROM a.before_snapshot->'reservations' OR actual->'reservation_locations' IS DISTINCT FROM a.before_snapshot->'reservation_locations' OR actual->'reservation_layers' IS DISTINCT FROM a.before_snapshot->'reservation_layers' THEN RAISE EXCEPTION 'Wykonanie zmieniło niezatwierdzony zakres' USING ERRCODE='23514';END IF;
 IF jsonb_array_length(d->'rows')<>jsonb_array_length(p.payload->'rows') OR EXISTS(SELECT 1 FROM jsonb_array_elements(d->'rows') rr WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') pr WHERE pr-'after'=rr-'after')) THEN RAISE EXCEPTION 'Wiersze wykonania nie odpowiadają zgodzie' USING ERRCODE='23514';END IF;
 rows_count:=0;
 FOR target IN SELECT value FROM jsonb_array_elements(p.payload->'targets') LOOP
  FOR child IN SELECT value FROM jsonb_array_elements(target->'children') LOOP
   rows_count:=rows_count+1;
   SELECT value INTO link FROM jsonb_array_elements(d->'links') x WHERE x->>'warehouse_id'=target->>'warehouse_id' AND coalesce(x->>'core_preview_id',x->>'stocktake_id')=child->>'id';
   IF link IS NULL THEN RAISE EXCEPTION 'Brak całego child receipt' USING ERRCODE='23514';END IF;
   IF(p.payload#>>'{policy,enabled}')::boolean THEN
    SELECT * INTO posting FROM wms_stocktake_postings WHERE tenant_id=t AND id=(link->>'posting_id')::uuid AND stocktake_id=(child->>'id')::uuid AND actor_id=a.actor_id AND client_key=(child->>'post_key')::uuid;
    IF posting.id IS NULL OR posting.review_id IS DISTINCT FROM(link->>'review_id')::uuid OR posting.operation_id IS DISTINCT FROM(link->>'operation_id')::uuid OR NOT EXISTS(SELECT 1 FROM wms_stocktakes h WHERE h.tenant_id=t AND h.id=posting.stocktake_id AND h.state='posted' AND h.posting_id=posting.id AND h.actor_id=a.actor_id AND h.warehouse_id=(target->>'warehouse_id')::uuid AND h.client_key=(child->>'create_key')::uuid) THEN RAISE EXCEPTION 'Brak rzeczywistego rozliczenia spisu' USING ERRCODE='23514';END IF;
    IF NOT EXISTS(SELECT 1 FROM stock_file_import_core_witnesses w WHERE w.tenant_id=t AND w.kind='wms_stocktake_postings' AND w.id=posting.id AND w.preview_id=p.id AND w.top_xid=pg_current_xact_id() AND w.transaction_started_at=transaction_timestamp()) OR NOT EXISTS(SELECT 1 FROM stock_file_import_core_witnesses w WHERE w.tenant_id=t AND w.kind='wms_stocktakes' AND w.id=posting.stocktake_id AND w.preview_id=p.id AND w.top_xid=pg_current_xact_id() AND w.transaction_started_at=transaction_timestamp()) THEN RAISE EXCEPTION 'Spis nie powstał w tej transakcji' USING ERRCODE='23514';END IF;
    IF(SELECT count(*) FROM wms_stocktake_lines WHERE tenant_id=t AND stocktake_id=posting.stocktake_id)<>(SELECT count(*) FROM jsonb_array_elements(p.payload->'rows') approved_row WHERE approved_row->>'warehouse_id'=target->>'warehouse_id' AND approved_row#>>'{input,operation}'='count') THEN RAISE EXCEPTION 'Spis rozszerzył zatwierdzone pozycje' USING ERRCODE='23514';END IF;
    FOR r IN SELECT value FROM jsonb_array_elements(p.payload->'rows') rr WHERE rr->>'warehouse_id'=target->>'warehouse_id' AND rr#>>'{input,operation}'='count' LOOP
     IF NOT EXISTS(SELECT 1 FROM wms_stocktake_lines l JOIN wms_stocktake_review_rows rw ON(rw.tenant_id,rw.line_id)=(l.tenant_id,l.id) WHERE l.tenant_id=t AND l.stocktake_id=posting.stocktake_id AND l.id=(r->>'line_id')::uuid AND l.product_id=(r->>'product_id')::uuid AND l.location=r->>'location' AND l.counted=(r#>>'{input,quantity}')::integer AND rw.review_id=posting.review_id AND rw.fragments=r->'fragments' AND rw.before->>'quantity'=r#>>'{before,quantity}' AND rw.after->>'quantity'=r#>>'{input,quantity}') THEN RAISE EXCEPTION 'Spis ma inne ilości, warstwy lub koszty' USING ERRCODE='23514';END IF;
    END LOOP;
   ELSE
    SELECT * INTO core FROM inventory_bulk_edit_executions WHERE tenant_id=t AND id=(link->>'core_execution_id')::uuid AND preview_id=(child->>'id')::uuid AND actor_id=a.actor_id AND client_key=(child->>'execute_key')::uuid;
    IF core.id IS NULL OR NOT EXISTS(SELECT 1 FROM stock_file_import_core_witnesses w WHERE w.tenant_id=t AND w.kind='inventory_bulk_edit_executions' AND w.id=core.id AND w.preview_id=p.id AND w.top_xid=pg_current_xact_id() AND w.transaction_started_at=transaction_timestamp()) OR NOT EXISTS(SELECT 1 FROM stock_file_import_core_witnesses w WHERE w.tenant_id=t AND w.kind='inventory_bulk_edit_previews' AND w.id=core.preview_id AND w.preview_id=p.id AND w.top_xid=pg_current_xact_id() AND w.transaction_started_at=transaction_timestamp()) THEN RAISE EXCEPTION 'Pomiar nie powstał w tej transakcji' USING ERRCODE='23514';END IF;
    IF EXISTS(SELECT 1 FROM inventory_bulk_edit_rows rr WHERE rr.tenant_id=t AND rr.preview_id=core.preview_id AND (rr.input->>'operation'<>'count' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') approved_row WHERE approved_row->>'warehouse_id'=target->>'warehouse_id' AND approved_row->>'product_id'=rr.product_id::text AND approved_row->>'location'=rr.location AND approved_row#>>'{input,quantity}'=rr.input->>'quantity'))) THEN RAISE EXCEPTION 'Child pomiar ma inny produkt lub ilość' USING ERRCODE='23514';END IF;
   END IF;
  END LOOP;
 END LOOP;
 IF jsonb_array_length(d->'links')<>rows_count THEN RAISE EXCEPTION 'Dodatkowe lub powtórzone child receipts' USING ERRCODE='23514';END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(d->'rows') LOOP
  IF r->'before'='null'::jsonb THEN IF r->'after' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Pominięty pomiar nie ma fizycznego after' USING ERRCODE='23514';END IF;CONTINUE;END IF;
  SELECT x INTO stockrow FROM jsonb_array_elements(actual->'stock') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id';
  IF r->'after' IS DISTINCT FROM jsonb_build_object('present',stockrow IS NOT NULL,'quantity',(r#>>'{input,quantity}')::integer,'reserved',(r#>>'{before,reserved}')::integer,'available',(r#>>'{input,quantity}')::integer-(r#>>'{before,reserved}')::integer,'warehouse_on_hand',coalesce((stockrow->>'on_hand')::integer,0),'warehouse_reserved',coalesce((stockrow->>'reserved')::integer,0),'stock_version',stockrow->>'version') THEN RAISE EXCEPTION 'Projekcja after nie odpowiada fizycznemu wynikowi' USING ERRCODE='23514';END IF;
 END LOOP;
 -- Independent final stock/bin conservation. Includes absent-to-zero and source epochs.
 FOR r IN SELECT DISTINCT jsonb_build_object('warehouse_id',rr->>'warehouse_id','product_id',rr->>'product_id') FROM jsonb_array_elements(p.payload->'rows') rr WHERE rr->>'product_id' IS NOT NULL LOOP
  SELECT x INTO oldrow FROM jsonb_array_elements(a.before_snapshot->'stock') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id';
  SELECT x INTO stockrow FROM jsonb_array_elements(actual->'stock') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id';
  SELECT coalesce(sum((rr#>>'{input,quantity}')::bigint-(rr#>>'{before,quantity}')::bigint),0) INTO delta FROM jsonb_array_elements(p.payload->'rows') rr WHERE rr->>'warehouse_id'=r->>'warehouse_id' AND rr->>'product_id'=r->>'product_id' AND rr#>>'{input,operation}'='count';
  IF coalesce((stockrow->>'on_hand')::bigint,0) IS DISTINCT FROM coalesce((oldrow->>'on_hand')::bigint,0)+delta OR coalesce((stockrow->>'reserved')::bigint,0) IS DISTINCT FROM coalesce((oldrow->>'reserved')::bigint,0) OR oldrow IS NULL AND delta=0 AND stockrow IS NOT NULL THEN RAISE EXCEPTION 'Fizyczny stan po pomiarze jest nieprawdziwy' USING ERRCODE='23514';END IF;
  SELECT coalesce((SELECT(x->>'version')::bigint FROM jsonb_array_elements(actual->'epochs') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id'),0)-coalesce((SELECT(x->>'version')::bigint FROM jsonb_array_elements(a.before_snapshot->'epochs') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id'),0) INTO expected;
  IF expected IS DISTINCT FROM (CASE WHEN oldrow IS NULL AND stockrow IS NOT NULL THEN 1::bigint ELSE 0::bigint END) THEN RAISE EXCEPTION 'Źródło brakującego stock zmieniło epokę' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR r IN SELECT DISTINCT jsonb_build_object('warehouse_id',rr->>'warehouse_id','product_id',rr->>'product_id','location',rr->>'location') FROM jsonb_array_elements(p.payload->'rows') rr WHERE rr#>>'{input,operation}'='count' LOOP
  SELECT x INTO oldrow FROM jsonb_array_elements(a.before_snapshot->'bins') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id' AND x->>'location'=r->>'location';
  SELECT x INTO binrow FROM jsonb_array_elements(actual->'bins') x WHERE x->>'warehouse_id'=r->>'warehouse_id' AND x->>'product_id'=r->>'product_id' AND x->>'location'=r->>'location';
  SELECT coalesce(sum((rr#>>'{input,quantity}')::bigint-(rr#>>'{before,quantity}')::bigint),0) INTO delta FROM jsonb_array_elements(p.payload->'rows') rr WHERE rr->>'warehouse_id'=r->>'warehouse_id' AND rr->>'product_id'=r->>'product_id' AND rr->>'location'=r->>'location' AND rr#>>'{input,operation}'='count';
  IF coalesce((binrow->>'quantity')::bigint,0) IS DISTINCT FROM coalesce((oldrow->>'quantity')::bigint,0)+delta OR oldrow IS NULL AND delta=0 AND binrow IS NOT NULL THEN RAISE EXCEPTION 'Stan binu po pomiarze jest nieprawdziwy' USING ERRCODE='23514';END IF;
 END LOOP;
 -- Preserve the full bin set outside the approved locations, including zero bins.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(a.before_snapshot->'bins') previous_bin WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'bins') current_bin WHERE current_bin->>'warehouse_id'=previous_bin->>'warehouse_id' AND current_bin->>'product_id'=previous_bin->>'product_id' AND current_bin->>'location'=previous_bin->>'location' AND current_bin-'quantity'=previous_bin-'quantity' AND (current_bin=previous_bin OR EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') approved_bin WHERE approved_bin#>>'{input,operation}'='count' AND approved_bin->>'warehouse_id'=previous_bin->>'warehouse_id' AND approved_bin->>'product_id'=previous_bin->>'product_id' AND approved_bin->>'location'=previous_bin->>'location')))) OR EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'bins') current_bin WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.before_snapshot->'bins') previous_bin WHERE previous_bin->>'warehouse_id'=current_bin->>'warehouse_id' AND previous_bin->>'product_id'=current_bin->>'product_id' AND previous_bin->>'location'=current_bin->>'location') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') approved_bin WHERE approved_bin#>>'{input,operation}'='count' AND approved_bin->>'warehouse_id'=current_bin->>'warehouse_id' AND approved_bin->>'product_id'=current_bin->>'product_id' AND approved_bin->>'location'=current_bin->>'location') AND NOT ((p.payload#>>'{policy,enabled}')::boolean AND current_bin->>'quantity'='0' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.before_snapshot->'stock') previous_stock WHERE previous_stock->>'warehouse_id'=current_bin->>'warehouse_id' AND previous_stock->>'product_id'=current_bin->>'product_id') AND EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'stock') current_stock WHERE current_stock->>'warehouse_id'=current_bin->>'warehouse_id' AND current_stock->>'product_id'=current_bin->>'product_id' AND current_stock->>'location'=current_bin->>'location'))) THEN RAISE EXCEPTION 'Wykonanie zmieniło niezatwierdzony zbiór binów' USING ERRCODE='23514';END IF;
 -- Each newly created core row covers an approved unique physical position exactly once.
 IF NOT(p.payload#>>'{policy,enabled}')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') approved_row WHERE approved_row#>>'{input,operation}'='count' AND(SELECT count(*) FROM jsonb_array_elements(d->'links') receipt_link JOIN inventory_bulk_edit_rows cr ON cr.tenant_id=t AND cr.preview_id=(receipt_link->>'core_preview_id')::uuid WHERE receipt_link->>'warehouse_id'=approved_row->>'warehouse_id' AND cr.product_id::text=approved_row->>'product_id' AND cr.location=approved_row->>'location')<>1) THEN RAISE EXCEPTION 'Niepełne fizyczne child rows' USING ERRCODE='23514';END IF;
 IF NOT(p.payload#>>'{policy,enabled}')::boolean THEN
  FOREACH name IN ARRAY ARRAY['lots','layers','layer_positions','wms_operations','wms_layer_movements'] LOOP IF actual->name IS DISTINCT FROM a.before_snapshot->name THEN RAISE EXCEPTION 'Wyłączony WMS nie może tworzyć warstw ani operacji' USING ERRCODE='23514';END IF;END LOOP;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'wms_operations') o WHERE NOT(a.before_snapshot->'wms_operations' @> jsonb_build_array(o)) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'links') l WHERE l->>'operation_id'=o->>'id')) THEN RAISE EXCEPTION 'WMS ma dodatkowe niezatwierdzone operacje' USING ERRCODE='23514';END IF;
 END IF;
 -- Journals are genuine core witnesses, not arbitrary extra adjustments.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(actual->'stock_movements') m WHERE NOT(a.before_snapshot->'stock_movements' @> jsonb_build_array(m)) AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.payload->'rows') rr WHERE rr->>'product_id'=m->>'product_id' AND rr->>'warehouse_id'=m->>'warehouse_id' AND rr->>'status'='changed') OR m->>'kind' IS DISTINCT FROM (CASE WHEN(p.payload#>>'{policy,enabled}')::boolean THEN 'wms_stocktake' ELSE 'location_count' END))) THEN RAISE EXCEPTION 'Dodatkowy niezatwierdzony ruch zapasu' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION stock_file_import_store_execution(d jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;BEGIN
 PERFORM stock_file_import_validate_execution(d);
 INSERT INTO stock_file_import_executions(id,tenant_id,preview_id,actor_id,api_key_id,client_key,request_hash,scope_hash,file_name,payload) VALUES((d->>'id')::uuid,t,(d->>'preview_id')::uuid,(d->>'actor_id')::uuid,(d->>'api_key_id')::uuid,(d->>'client_key')::uuid,d->>'request_hash',d->>'scope_hash',d->>'file_name',d);
 UPDATE stock_file_import_admissions SET after_snapshot=d->'snapshot' WHERE tenant_id=t AND execution_id=(d->>'id')::uuid;PERFORM stock_file_import_budget_check(t);
END $$;
CREATE FUNCTION stock_file_import_budget_check(t uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE n bigint:=0;b bigint;name text;BEGIN
 FOR name IN SELECT unnest(ARRAY['stock_file_import_previews','stock_file_import_executions','stock_file_import_profiles','stock_file_import_profile_revisions','stock_file_import_admissions','stock_file_import_core_witnesses']) LOOP EXECUTE format('SELECT coalesce(sum(octet_length(to_jsonb(p)::text)),0) FROM %I p WHERE tenant_id=$1',name) INTO b USING t;n:=n+b;END LOOP;IF n>268435456 THEN RAISE EXCEPTION 'Budżet dowodów importu stanów' USING ERRCODE='P0001';END IF;END $$;
CREATE FUNCTION stock_file_import_store_profile(d jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;old stock_file_import_profiles%ROWTYPE;target jsonb;BEGIN
 PERFORM stock_file_import_require((d->>'actor_id')::uuid,(d->>'api_key_id')::uuid,false);
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(d) x WHERE x NOT IN('id','version','client_key','name','definition','targets','actor_id','api_key_id','request_hash','source')) OR NOT stock_file_import_configuration(d->'definition',d->'targets') OR jsonb_array_length(d->'targets') NOT BETWEEN 1 AND 8 OR d->>'name' IS NULL OR length(d->>'name') NOT BETWEEN 1 AND 120 OR(d->>'version')::integer<1 THEN RAISE EXCEPTION 'Niepoprawny profil pomiarów' USING ERRCODE='23514';END IF;
 FOR target IN SELECT value FROM jsonb_array_elements(d->'targets') LOOP IF NOT EXISTS(SELECT 1 FROM warehouses WHERE tenant_id=t AND id=(target->>'warehouse_id')::uuid) THEN RAISE EXCEPTION 'Obcy magazyn profilu' USING ERRCODE='23514';END IF;END LOOP;
 SELECT * INTO old FROM stock_file_import_profiles WHERE tenant_id=t AND id=(d->>'id')::uuid FOR UPDATE;
 IF(d->>'version')::integer<>coalesce(old.version,0)+1 THEN RAISE EXCEPTION 'Wersja profilu pomiarów zmieniła się' USING ERRCODE='23514';END IF;
 IF old.id IS NULL THEN INSERT INTO stock_file_import_profiles(id,tenant_id,version,payload) VALUES((d->>'id')::uuid,t,1,d);ELSE UPDATE stock_file_import_profiles SET version=(d->>'version')::integer,payload=d WHERE tenant_id=t AND id=old.id;END IF;
 INSERT INTO stock_file_import_profile_revisions(tenant_id,profile_id,version,actor_id,api_key_id,client_key,request_hash,payload) VALUES(t,(d->>'id')::uuid,(d->>'version')::integer,(d->>'actor_id')::uuid,(d->>'api_key_id')::uuid,(d->>'client_key')::uuid,d->>'request_hash',d);
END $$;
CREATE FUNCTION stock_file_import_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE a stock_file_import_admissions%ROWTYPE;e stock_file_import_executions%ROWTYPE;child uuid;BEGIN
 IF TG_TABLE_NAME='stock_file_import_admissions' THEN SELECT * INTO a FROM stock_file_import_admissions WHERE(tenant_id,execution_id)=(NEW.tenant_id,NEW.execution_id);
 ELSE
  IF to_regclass('public.stock_file_import_admissions') IS NULL THEN RETURN NEW;END IF;
  child:=CASE WHEN TG_TABLE_NAME='inventory_bulk_edit_executions' THEN(to_jsonb(NEW)->>'preview_id')::uuid WHEN TG_TABLE_NAME='wms_stocktake_postings' THEN(to_jsonb(NEW)->>'stocktake_id')::uuid ELSE NEW.id END;
  SELECT adm.* INTO a FROM stock_file_import_admissions adm JOIN stock_file_import_previews p ON(p.tenant_id,p.id)=(adm.tenant_id,adm.preview_id) CROSS JOIN LATERAL jsonb_array_elements(p.payload->'targets') target CROSS JOIN LATERAL jsonb_array_elements(target->'children') c WHERE adm.tenant_id=NEW.tenant_id AND(c->>'id')::uuid=child AND adm.top_xid=pg_current_xact_id() AND adm.transaction_started_at=transaction_timestamp();
  IF a.execution_id IS NULL THEN RETURN NEW;END IF;
 END IF;
 SELECT * INTO e FROM stock_file_import_executions WHERE(tenant_id,id)=(a.tenant_id,a.execution_id);
 IF e.id IS NULL OR a.after_snapshot IS NULL THEN RAISE EXCEPTION 'Niekompletny cały import pomiarów' USING ERRCODE='23514';END IF;
 IF a.top_xid=pg_current_xact_id() AND a.transaction_started_at=transaction_timestamp() THEN PERFORM stock_file_import_validate_execution(e.payload);PERFORM stock_file_import_require(a.actor_id,a.api_key_id,true);END IF;RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER complete AFTER INSERT OR UPDATE ON stock_file_import_admissions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION stock_file_import_complete();
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['inventory_bulk_edit_previews','inventory_bulk_edit_executions','wms_stocktakes','wms_stocktake_postings'] LOOP EXECUTE format('CREATE TRIGGER stock_file_witness AFTER INSERT ON %I FOR EACH ROW EXECUTE FUNCTION stock_file_import_core_witness()',n);EXECUTE format('CREATE CONSTRAINT TRIGGER stock_file_receipt AFTER INSERT ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION stock_file_import_complete()',n);END LOOP;END $$;
CREATE FUNCTION stock_file_import_seal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE oldtenant uuid;newtenant uuid;BEGIN
 IF TG_OP<>'INSERT' THEN oldtenant:=(to_jsonb(OLD)->>'tenant_id')::uuid;END IF;IF TG_OP<>'DELETE' THEN newtenant:=(to_jsonb(NEW)->>'tenant_id')::uuid;END IF;
 IF to_regclass('public.stock_file_import_executions') IS NULL THEN RETURN coalesce(NEW,OLD);END IF;
 IF EXISTS(SELECT 1 FROM stock_file_import_executions e WHERE e.tenant_id IN(oldtenant,newtenant) AND e.top_xid=pg_current_xact_id() AND e.transaction_started_at=transaction_timestamp()) THEN RAISE EXCEPTION 'Zatwierdzony cały import stanów jest zapieczętowany' USING ERRCODE='23514';END IF;RETURN coalesce(NEW,OLD);
END $$;
DO $$ DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['products','product_sku_aliases','warehouses','stock','stock_locations','reservations','reservation_locations','wms_lots','wms_cost_layers','wms_layer_positions','wms_reservation_layers','wms_operations','wms_layer_movements','stock_movements','stock_location_movements','stock_location_operations','wms_stocktakes','wms_stocktake_lines','wms_stocktake_reviews','wms_stocktake_review_rows','wms_stocktake_postings','wms_stocktake_measurements','wms_stocktake_measurement_layers','wms_stocktake_scope_layers','inventory_bulk_edit_previews','inventory_bulk_edit_rows','inventory_bulk_edit_executions','inventory_bulk_edit_execution_rows','wms_policies'] LOOP EXECUTE format('CREATE TRIGGER stock_file_seal BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION stock_file_import_seal()',n);END LOOP;END $$;
CREATE FUNCTION stock_file_import_metadata_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN PERFORM stock_file_import_require(NEW.actor_id,NEW.api_key_id,true);RETURN NEW;END $$;
CREATE CONSTRAINT TRIGGER complete AFTER INSERT ON stock_file_import_previews DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION stock_file_import_metadata_complete();
CREATE CONSTRAINT TRIGGER complete AFTER INSERT ON stock_file_import_profile_revisions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION stock_file_import_metadata_complete();
-- All internal functions stay private; only typed scoped entry points are app-callable.
DO $$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'stock_file_import_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,dyna_app',f.signature);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION stock_file_import_installed(),stock_file_import_access(uuid,uuid,boolean,boolean),stock_file_import_snapshot(jsonb),stock_file_import_store_preview(jsonb),stock_file_import_prepare(uuid,uuid,uuid,uuid,jsonb),stock_file_import_store_execution(jsonb),stock_file_import_store_profile(jsonb),stock_file_import_core_admitted(uuid,uuid,text) TO dyna_app;
